CREATE TABLE "members" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,    "first_name" VARCHAR(100) NOT NULL,    "last_name" VARCHAR(100) NOT NULL,    "email" VARCHAR(320) NOT NULL,    "membership_number" VARCHAR(20) NOT NULL,    "membership_type" VARCHAR(50) NOT NULL DEFAULT 'Standard',    CONSTRAINT pk_members PRIMARY KEY (id),    CONSTRAINT uq_members_email UNIQUE (email),    CONSTRAINT uq_members_membership_number UNIQUE (membership_number),    CONSTRAINT chk_members_membership_type_enum CHECK (membership_type IN ('Standard', 'Premium', 'Student')));
